-- SQL generated by Prisma based on schema.prisma
CREATE TYPE "CarStatus" AS ENUM ('AVAILABLE', 'RESERVED', 'SOLD');
CREATE TYPE "UserRole" AS ENUM ('ADMIN');

CREATE TABLE "Model" (
  "id" SERIAL PRIMARY KEY,
  "brand" TEXT NOT NULL,
  "modelName" TEXT NOT NULL,
  "bodyType" TEXT NOT NULL,
  "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updatedAt" TIMESTAMP(3) NOT NULL,
  UNIQUE("brand", "modelName")
);

CREATE TABLE "Car" (
  "id" SERIAL PRIMARY KEY,
  "modelId" INTEGER NOT NULL REFERENCES "Model"("id") ON DELETE RESTRICT ON UPDATE CASCADE,
  "year" INTEGER NOT NULL,
  "price" DECIMAL(12,2) NOT NULL,
  "mileage" INTEGER NOT NULL,
  "engine" TEXT NOT NULL,
  "transmission" TEXT NOT NULL,
  "fuelType" TEXT NOT NULL,
  "color" TEXT NOT NULL,
  "description" TEXT NOT NULL,
  "imageUrl" TEXT NOT NULL,
  "status" "CarStatus" NOT NULL DEFAULT 'AVAILABLE',
  "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updatedAt" TIMESTAMP(3) NOT NULL
);

CREATE TABLE "Client" (
  "id" SERIAL PRIMARY KEY,
  "fullName" TEXT NOT NULL,
  "phone" TEXT NOT NULL,
  "email" TEXT NOT NULL,
  "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  UNIQUE("phone", "email")
);

CREATE TABLE "Application" (
  "id" SERIAL PRIMARY KEY,
  "clientId" INTEGER NOT NULL REFERENCES "Client"("id") ON DELETE CASCADE ON UPDATE CASCADE,
  "carId" INTEGER NOT NULL REFERENCES "Car"("id") ON DELETE CASCADE ON UPDATE CASCADE,
  "message" TEXT NOT NULL,
  "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE "TestDrive" (
  "id" SERIAL PRIMARY KEY,
  "clientId" INTEGER NOT NULL REFERENCES "Client"("id") ON DELETE CASCADE ON UPDATE CASCADE,
  "carId" INTEGER NOT NULL REFERENCES "Car"("id") ON DELETE CASCADE ON UPDATE CASCADE,
  "preferredDate" TIMESTAMP(3) NOT NULL,
  "comment" TEXT NOT NULL,
  "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE "User" (
  "id" SERIAL PRIMARY KEY,
  "login" TEXT NOT NULL UNIQUE,
  "passwordHash" TEXT NOT NULL,
  "role" "UserRole" NOT NULL DEFAULT 'ADMIN',
  "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP
);
